add_filter( 'woocommerce_product_tabs', 'perfectpixel_custom_product_tab' );

function perfectpixel_custom_product_tab( $tabs ) {
	$categories = wp_parse_id_list( '{{custom_tab_category_ids}}' );
	if ( $categories && ! has_term( $categories, 'product_cat', get_the_ID() ) ) {
		return $tabs;
	}
	$tabs['perfectpixel_custom'] = array(
		'title'    => '{{custom_tab_title}}',
		'priority' => (int) '{{custom_tab_priority}}',
		'callback' => 'perfectpixel_custom_product_tab_content',
	);
	return $tabs;
}

function perfectpixel_custom_product_tab_content() {
	echo '<h2>' . esc_html( '{{custom_tab_title}}' ) . '</h2>';
	echo wp_kses_post( do_shortcode( '{{custom_tab_content}}' ) );
}
